```c
struct node { int d; struct node *next; };
struct node *g(struct node *h, int k) {
    struct node *p = h, *prev = NULL, *nx;
    int c = 0;
    while (p && c < k) { p = p->next; c++; }
    if (c < k) return h;
    p = h; c = 0;
    while (p && c < k) { nx = p->next; p->next = prev; prev = p; p = nx; c++; }
    h->next = g(p, k);
    return prev;
}
